const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roles={home:{name:'Proprietario',label:'Dimora Home',title:'La tua casa, senza pensieri.',benefit:'Documenti, oggetti e scadenze: ritrova tutto quando serve.',nav:['La mia casa','Oggetti e stanze','Documenti','Attività','Spese e previsioni','Storia della casa','Condominio','Condivisioni','Piano e preferenze'],journey:['La mia casa','Documenti','Oggetti e stanze','Attività','Condivisioni']},agency:{name:'Agenzia',label:'Dimora per le agenzie',title:'Ogni immobile, pronto al prossimo passo.',benefit:'Dalla raccolta dei documenti alla consegna della memoria della casa.',nav:['Panoramica','Fascicoli','Checklist','Dossier acquirente','Home Gift','Team e strumenti'],journey:['Fascicoli','Checklist','Dossier acquirente','Home Gift']},admin:{name:'Amministratore',label:'Dimora per gli amministratori',title:'Conosci gli edifici. Anticipa le attenzioni.',benefit:'Una memoria tecnica ordinata, da condividere con chi ne ha diritto.',nav:['Panoramica','Edifici','Impianti e memoria','Scadenze','Budget e previsioni','Pubblicazioni','Segnalazioni','Unità e accessi','Team e strumenti'],journey:['Edifici','Impianti e memoria','Pubblicazioni','Unità e accessi']}};
let state={role:'home',page:'La mia casa',filter:'Tutti',query:'',tour:false,step:0,reviewed:false,completed:false,published:false,gift:false,linked:false,activity:'Manutenzione caldaia',extraDocs:[],objects:[],expenses:[],selected:'Via Roma 12',budget:18000,changes:[]};
const docs=[{name:'Manuale caldaia',type:'Impianti',source:'Archivio personale · originale',icon:'▤'},{name:'Fattura manutenzione',type:'Spese',source:'Archivio personale · 12 ottobre 2026',icon:'€'},{name:'Planimetria della casa',type:'Casa',source:'Archivio personale · versione 1',icon:'⌂'},{name:'Rapporto ascensore',type:'Condominio',source:'Studio Verdi · versione 3',icon:'▥'}];
function button(label,action,light=false){return `<button class="btn ${light?'light':''}" data-action="${esc(action)}">${label}</button>`}function pill(t){return `<span class="pill green">${t}</span>`}function row(title,sub,action,label='Apri',icon='▤'){return `<div class="row"><div class="row-icon">${icon}</div><div class="rowbody"><strong>${esc(title)}</strong><p>${esc(sub)}</p></div>${action?`<button class="btn light small" data-action="${esc(action)}">${label}</button>`:''}</div>`}function card(title,body){return `<section class="card"><h3>${title}</h3>${body}</section>`}function metrics(items){return `<div class="metrics">${items.map(([label,n,sub])=>`<div class="metric"><span>${label}</span><strong>${n}</strong><span>${sub}</span></div>`).join('')}</div>`}
function houseArt(){return `<svg viewBox="0 0 500 430" role="img" aria-label="Illustrazione di una casa con stanze, documenti e verde"><ellipse cx="257" cy="366" rx="188" ry="32" fill="#b6c8a6"/><path d="M97 189 250 87 405 189v160H97Z" fill="#f6f4e6"/><path d="m75 192 174-123 179 123-15 20-164-111L90 211Z" fill="#547252"/><path d="M249 103v246H99V203Z" fill="#fdfbf2"/><path d="M249 103v246h153V203Z" fill="#e9e5d0"/><path d="M250 117v232M100 252h302" fill="none" stroke="#c5cdb4" stroke-width="5"/><path d="M191 349v-64h42v64" fill="#6a8a63"/><rect x="124" y="274" width="44" height="44" rx="3" fill="#b9d6cb"/><path d="M146 274v44M124 296h44" stroke="#faf9f0" stroke-width="4"/><rect x="285" y="190" width="70" height="40" rx="4" fill="#b3c4a0"/><rect x="275" y="217" width="90" height="20" rx="6" fill="#8ea67c"/><rect x="285" y="234" width="6" height="10" fill="#546c48"/><rect x="347" y="234" width="6" height="10" fill="#546c48"/><rect x="282" y="280" width="87" height="48" fill="#cab888"/><rect x="289" y="288" width="30" height="30" fill="#ecdfba"/><rect x="328" y="288" width="32" height="30" fill="#ecdfba"/><rect x="151" y="192" width="47" height="39" fill="#d9b774"/><path d="m152 188 23-18 23 18" fill="#c09c5c"/><circle cx="397" cy="296" r="32" fill="#88a474"/><circle cx="417" cy="270" r="23" fill="#9fb88b"/><path d="M400 293v63" stroke="#6e7956" stroke-width="7"/><circle cx="82" cy="327" r="23" fill="#a2b98a"/><path d="M82 331v26" stroke="#6e7956" stroke-width="5"/><path d="M196 369h53l-14-20h-39Z" fill="#e9e9d7"/><circle cx="355" cy="93" r="24" fill="#e5d49d"/></svg>`}
function landing(){return `<div class="landing"><header class="top"><button class="brand" data-action="landing">dimora<span>.</span></button><nav><button class="link" data-action="scroll:profiles">Per chi è</button><button class="link" data-action="scroll:how">Come funziona</button><span class="pill">Demo interattiva</span>${button('Esplora Dimora ↗','enter:home')}</nav></header><main><section class="hero"><div><div class="eyebrow">La memoria digitale della tua casa</div><h1>La casa cambia.<br>La sua storia<br>resta con te.</h1><p>Documenti, impianti, spese e persone.<br>Dimora dà un posto a tutto quello che conta, per prenderti cura della casa con più semplicità.</p><div class="actions">${button('Entra nella tua casa →','enter:home')}${button('Scopri i tre profili','scroll:profiles',true)}</div><span class="tiny">Nessuna registrazione · Esplora con dati di esempio</span></div><div class="scene">${houseArt()}<div class="float f1"><strong><span class="tick">✓</span>Tutto al suo posto</strong>Un documento. Tante informazioni.</div><div class="float f2"><strong>⌂ La tua casa ha memoria</strong>Oggetti, fonti e storia collegati.</div></div></section><div class="strip"><span>⌂ Una memoria che accompagna l’immobile</span><span>▤ Le informazioni, quando servono</span><span>↗ Condividi solo quello che scegli</span></div><section class="section" id="profiles"><div class="section-heading"><div class="eyebrow">Tre prospettive. Una casa al centro.<h2 style="margin:16px 0 0;text-transform:none;letter-spacing:-1px">Da qualunque parte la vivi.</h2></div><p>Scegli il tuo profilo e prova un percorso completo. Puoi cambiare prospettiva in ogni momento.</p></div><div class="profiles">${[['home','⌂','Vivi la casa. Al resto dai un posto.','Per chi possiede o gestisce la propria casa.',['Ritrova documenti e garanzie','Ricorda le manutenzioni','Segui spese e storia della casa']],['agency','↗','Il valore continua dopo le chiavi.','Per chi accompagna una compravendita.',['Raccogli i documenti in un fascicolo','Prepara un dossier selezionato','Consegna una Home Gift']],['admin','▥','La memoria degli edifici, organizzata.','Per chi amministra uno o più condomìni.',['Collega impianti, fonti e scadenze','Pianifica gli interventi','Pubblica alle unità autorizzate']]].map(([r,i,t,p,ls])=>`<article class="profile"><div class="symbol">${i}</div><div class="eyebrow">${roles[r].name}</div><h3>${t}</h3><p>${p}</p><ul>${ls.map(x=>`<li>${x}</li>`).join('')}</ul>${button('Prova il profilo →','enter:'+r,true)}</article>`).join('')}</div></section><section class="section" id="how"><div class="how"><div><div class="eyebrow" style="color:#c8dea8">Meno passaggi. Più chiarezza.</div><h2>Dal documento alla memoria della casa.</h2><p>Una fattura può raccontare un acquisto, una spesa, un professionista. Dimora mette in relazione le informazioni e ti lascia l’ultima parola.</p>${button('Prova un documento di esempio','demo:import',true)}</div><div class="steps"><div class="step"><b>1</b><div>Porta i documenti<p>Foto, PDF e importazioni: nel prototipo usi esempi già pronti.</p></div></div><div class="step"><b>2</b><div>Rivedi le proposte<p>Oggetti, costi e date, con la fonte sempre visibile.</p></div></div><div class="step"><b>3</b><div>Ritrova tutto collegato<p>La casa prende forma. Tu scegli cosa conservare e condividere.</p></div></div></div></div></section></main><footer><span class="brand" style="font-size:22px">dimora.</span><span>Prototipo promozionale · Dati fittizi · Azioni simulate</span><span>Home · Agenzie · Amministratori</span></footer></div>`}
function dashboard(){const r=state.role;if(r==='home')return `<div class="banner"><div><div class="eyebrow" style="margin-bottom:8px">Il prossimo piccolo passo</div><h3>${state.reviewed?'La tua casa è un po’ più completa.':'Un documento può raccontarti di più.'}</h3><p>${state.reviewed?'Hai confermato le informazioni della fattura dimostrativa.':'Prova a trasformare una fattura in un oggetto, una spesa e un contatto.'}</p></div>${button(state.reviewed?'Vedi gli oggetti →':'Prova con una fattura →',state.reviewed?'nav:Oggetti e stanze':'import')}</div>${metrics([['Documenti',docs.length+state.extraDocs.length,'Originali e fonti collegati'],['Da rivedere',state.reviewed?'0':'1','Decidi tu cosa confermare'],['Prossime attività',state.completed?'1':'2','La casa sotto controllo']])}<div class="columns">${card('La tua casa, stanza per stanza',row('Cucina','Lavastoviglie · manuale e garanzia','detail:Lavastoviglie','Esplora','⌂')+row('Locale tecnico','Caldaia · libretto e interventi','detail:Caldaia','Esplora','♧')+row('Tutti gli ambienti','Oggetti, impianti e pertinenze','nav:Oggetti e stanze','Vedi tutto','▦'))}${card('Da ricordare',row(state.activity,state.completed?'Completata · prossimo promemoria preparato':'5 novembre 2026 · attività dimostrativa','complete',state.completed?'Dettagli':'Gestisci','◷')+row('I documenti del condominio','Fonte: Studio Verdi · documenti comuni','nav:Condominio','Consulta','▥'))}</div>`;return `<div class="banner"><div><h3>${r==='agency'?'Dall’incarico alle chiavi. Un percorso ordinato.':'Il patrimonio tecnico, sempre a portata di mano.'}</h3><p>${roles[r].benefit}</p></div>${button('Inizia il percorso →','tour')}</div>${metrics(r==='agency'?[['Fascicoli','2','Esempi navigabili'],['Da richiedere','2','Documenti della pratica selezionata'],['Home Gift',state.gift?'1':'0','Consegne simulate']]:[['Edifici','2','Portafoglio dimostrativo'],['Attenzioni','2','Impianti e documenti da rivedere'],['Pubblicazioni',state.published?'1':'0','Contenuti selezionati']])}<div class="columns">${card(r==='agency'?'I tuoi fascicoli':'I tuoi edifici',row('Via Roma 12','Milano · '+(r==='agency'?'Vendita · raccolta in corso':'24 unità · 3 impianti comuni'),'select:Via Roma 12','Apri','⌂')+row('Via dei Tigli 8','Torino · '+(r==='agency'?'Vendita · dossier da preparare':'18 unità · 2 impianti comuni'),'select:Via dei Tigli 8','Apri','⌂'))}${card('Una sola prossima azione',row(r==='agency'?'Completa la raccolta':'Controlla la memoria tecnica',r==='agency'?'Richiedi i documenti mancanti.':'Ritrova la fonte dell’ultimo intervento.',r==='agency'?'nav:Checklist':'nav:Impianti e memoria','Continua','→'))}</div>`}
function documents(){let list=[...docs,...state.extraDocs].filter(d=>(state.filter==='Tutti'||state.filter===d.type)&&d.name.toLowerCase().includes(state.query.toLowerCase()));return `<div class="filter">${['Tutti','Casa','Impianti','Spese','Condominio'].map(t=>`<button class="${state.filter===t?'active':''}" data-action="filter:${t}">${t}</button>`).join('')}</div>${card('L’archivio della casa',list.map(d=>row(d.name,d.source,'document:'+d.name,'Apri',d.icon)).join('')||'<div class="empty">Nessun documento con questi filtri.</div>')}<div class="source">Originali, provenienza e versioni restano collegati alle informazioni. La ricerca riguarda questo archivio dimostrativo.</div>`}
function objects(){return `<div class="gridcards">${[['Lavastoviglie','Cucina · Bosch · esempio','▦'],['Caldaia','Locale tecnico · Vaillant · esempio','♧'],...state.objects.map(n=>[n,'Confermato dal documento demo','▦']),['Gli ambienti','Cucina, soggiorno, camera e locale tecnico','⌂']].map(([t,s,i])=>card(`<div class="bigicon">${i}</div>${t}`,`<p>${s}</p>${button('Esplora →','detail:'+t,true)}`)).join('')}</div><p class="routehint">Ogni oggetto raccoglie documenti, spese, attività, contatti e garanzie. Le informazioni mancanti restano da completare.</p>`}
function tasks(){return card('Le prossime attenzioni',row(state.activity,state.completed?'Completata · prossimo promemoria 5 novembre 2027':'5 novembre 2026 · Manutenzione programmata','complete',state.completed?'Rivedi':'Completa','◷')+row('Controlla la garanzia lavastoviglie','Scadenza inserita manualmente · esempio','detail:Lavastoviglie','Apri','▦')+(!state.reviewed?row('Una proposta da rivedere','Documento dimostrativo · niente salvato automaticamente','review','Rivedi','▤'):''))+card('Un promemoria semplice','<p>Dai un nome all’attività e scegli la data. Dopo il completamento puoi preparare il prossimo appuntamento.</p>'+button('Aggiungi un’attività','new:activity',true))}
function expenses(){let total=120+state.expenses.reduce((a,x)=>a+x.amount,0);return metrics([['Spese documentate',money(total),'Dati di esempio'],['Fonte','Fatture','Ogni costo resta collegato'],['Orizzonte','5 anni','Scenario modificabile']])+card('I costi, con il loro contesto',row('Manutenzione caldaia','12 ottobre 2026 · fattura dimostrativa · € 120','document:Fattura manutenzione','Fonte','€')+state.expenses.map(x=>row(x.name,'Confermato in demo · '+money(x.amount),'document:Fattura acquisto demo','Fonte','€')).join(''))+forecast(false)}
function money(n){return new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n)}function forecast(admin){return card('Uno sguardo alle spese future',`<p>Modifica il costo annuo per esplorare uno scenario. Gli importi sono ipotesi dimostrative, non preventivi.</p><label for="annual">${admin?'Manutenzione annua del fabbricato':'Spesa annua ipotizzata'} (€)</label><input id="annual" type="number" min="0" max="10000000" value="${admin?state.budget:2400}" style="padding:10px;border:1px solid #dfe5db;border-radius:8px;margin:12px 0;width:160px"><div id="chart">${chart(admin?state.budget:2400)}</div><p class="tiny">Scenario: incremento annuo del 2%. Nessun riparto millesimale o tariffa reale.</p>`)}function chart(base){return [2027,2028,2029,2030,2031].map((y,i)=>`<div class="chartrow"><span>${y}</span><div class="bar"><i style="width:${Math.max(0,Math.min(100,65*Math.pow(1.02,i)))}%"></i></div><strong>${money(base*Math.pow(1.02,i))}</strong></div>`).join('')}
function checklist(){return card('Fascicolo · '+esc(state.selected),`<p>Una lista chiara di ciò che è presente e di ciò che serve ancora. La completezza documentale non è una verifica di conformità.</p>${[['Atto di provenienza',true],['Planimetria catastale',true],['APE',state.changes.includes('APE')],['Libretto impianto',state.changes.includes('Libretto impianto')]].map(([t,ok])=>`<div class="row"><div class="rowbody"><strong>${t}</strong><p>${ok?'Ricevuto · da verificare':'Da richiedere al proprietario'}</p></div>${ok?pill('Ricevuto'):`<button class="btn light small" data-action="receive:${t}">Simula ricezione</button>`}</div>`).join('')}<div class="actions" style="margin-top:20px">${button('Prepara richiesta documenti','request')}${button('Vai al dossier →','nav:Dossier acquirente',true)}</div>`)}
function publications(){return card('Scegli cosa rendere disponibile',`<p>Un documento archiviato resta interno finché scegli contenuti e destinatari.</p><label class="check"><input type="checkbox" id="pub-doc" checked><span>Rapporto ascensore · versione 3<small>Documento tecnico · edificio ${esc(state.selected)}</small></span></label><label class="check"><input type="checkbox" id="pub-update"><span>Aggiornamento manutenzione<small>Intervento programmato · contenuto dimostrativo</small></span></label><p style="margin-top:20px">Destinatari: unità autorizzate della Scala A.</p>${button(state.published?'Rivedi la pubblicazione':'Anteprima pubblicazione','publish')}`)+(state.published?`<div class="banner"><div><h3>Pubblicazione simulata pronta.</h3><p>Fonte, versione e destinatari sono visibili nel riepilogo.</p></div>${button('Vedi come proprietario →','condo',true)}</div>`:'')}
function pageContent(){const p=state.page;if(p==='La mia casa'||p==='Panoramica')return dashboard();if(p==='Documenti')return documents();if(p==='Oggetti e stanze')return objects();if(p==='Attività'||p==='Scadenze')return tasks();if(p==='Spese e previsioni')return expenses();if(p==='Budget e previsioni')return forecast(true);if(p==='Storia della casa')return card('Ogni passaggio lascia una traccia',row('12 ottobre 2026 · Manutenzione caldaia','Intervento collegato a documento, spesa e professionista','document:Fattura manutenzione','Vedi fonte','◷')+row('Giugno 2026 · Acquisto lavastoviglie','Manuale, fattura e garanzia manuale','detail:Lavastoviglie','Esplora','▦')+state.changes.filter(x=>x==='Acquisto confermato').map(x=>row(x,'Oggi · fattura acquisto demo','detail:Macchina da caffè','Apri','☕')).join(''));if(p==='Condominio')return `<div class="banner"><div><h3>La casa incontra il condominio.</h3><p>Informazioni comuni dallo Studio Verdi, distinte dai tuoi documenti personali.</p></div>${pill('Scala A · Interno 12')}</div>${card('La memoria comune',row('Rapporto ascensore','Studio Verdi · versione 3'+(state.published?' · pubblicazione simulata':' · esempio già pubblicato'),'document:Rapporto ascensore','Consulta','▥')+row('Manutenzione ascensore','Aggiornamento dello studio: intervento programmato','notice','Leggi','◷'))}${button('Segnala un problema','issue',true)}`;if(p==='Condivisioni')return card('Tu scegli cosa esce dalla tua casa',`<p>Prepara un pacchetto per un familiare, un professionista o un futuro proprietario. I dati personali restano esclusi per impostazione iniziale.</p>${button('Scegli documenti e destinatario','share')}`);if(p==='Piano e preferenze')return `<div class="gridcards">${card('Home Free','<p>Gestione manuale della casa, consultazione, modifica ed esportazione dei propri dati.</p>'+pill('Piano dimostrativo'))}${card('Home Pro','<p>Proposte AI e automazioni entro quote da definire. Nel prototipo puoi esplorarle in simulazione.</p>'+button('Scopri la proposta','plan',true))}${card('Le tue preferenze','<p>Scegli promemoria e canali di notifica, consulta ed esporta la memoria della casa.</p>'+button('Preferenze demo','preferences',true))}</div>`;if(p==='Fascicoli'||p==='Edifici')return card(p+' dimostrativi',row('Via Roma 12','Milano · '+(state.role==='agency'?'raccolta documentale':'24 unità, scala A e B'),'select:Via Roma 12','Apri','⌂')+row('Via dei Tigli 8','Torino · '+(state.role==='agency'?'dossier da preparare':'18 unità, scala unica'),'select:Via dei Tigli 8','Apri','⌂'))+button(state.role==='agency'?'Nuovo fascicolo':'Nuovo edificio','new:property',true);if(p==='Checklist')return checklist();if(p==='Dossier acquirente')return card('Il dossier giusto, per la persona giusta',`<p>${esc(state.selected)} · scegli il livello e i documenti che possono essere mostrati.</p><div class="gridcards">${card('Anteprima','<p>Informazioni divulgabili dell’immobile.</p>'+button('Visualizza','dossier:Anteprima',true))}${card('Riservato','<p>Documenti selezionati per destinatario.</p>'+button('Seleziona','dossier:Riservato',true))}${card('Home Gift','<p>Una consegna permanente distinta.</p>'+button('Prepara','nav:Home Gift',true))}</div>`);if(p==='Home Gift')return card('Le chiavi. E tutto quello che serve dopo.',`<p>Consegna al nuovo proprietario una memoria della casa con documenti, oggetti e storia selezionati. L’invito non crea un account automaticamente.</p>${row('Documenti della casa','Planimetria, manuale impianto · selezione da confermare',null)}${row('Memoria strutturata','Schede impianti e provenienza · nessun dato personale',null)}<div class="actions" style="margin-top:20px">${button(state.gift?'Rivedi Home Gift':'Prepara la consegna','gift')}${state.gift?button('Esplora la Home del destinatario →','gift-home',true):''}</div>`);if(p==='Impianti e memoria')return card('Edificio · '+esc(state.selected),row('Ascensore Scala A','Rapporto v3 · ultimo intervento documentato','detail:Ascensore','Esplora','▥')+row('Centrale termica','Libretto presente · dato tecnico da confermare','detail:Centrale termica','Esplora','♧'))+button('Importa documenti di esempio','import',true);if(p==='Pubblicazioni')return publications();if(p==='Segnalazioni')return card('Le richieste, con il loro contesto',row('Ascensore fermo · Scala A','Già presente un aggiornamento dello studio','notice','Apri','◷')+row('Illuminazione ingresso','Segnalazione dimostrativa · ricevuta','resolve','Gestisci','☼'));if(p==='Unità e accessi')return card('Un accesso legato alla giusta unità',row('Scala A · Interno 12',state.linked?'Invito predisposto in simulazione':'Proprietario da collegare','invite','Prepara invito','⌂')+row('Cambio proprietario','Rivedi data di efficacia e accessi precedenti','ownership','Simula','↗'));if(p==='Team e strumenti')return card('Il tuo lavoro, con le persone giuste',row('Collaboratori','Ruoli e accessi della singola organizzazione','team','Gestisci','♧')+row('Importazioni e integrazioni','Anteprima di import da file compatibili · nessun gestionale connesso','integration','Esplora','↗')+row('Identità dello studio','Anteprima del marchio sui dossier','branding','Personalizza','▤'));return ''}
function workspace(){const r=roles[state.role],home=state.page===r.nav[0];return `<div class="demo-bar">DEMO INTERATTIVA · Dati di esempio · Nessun invio o servizio reale</div><div class="workspace"><aside class="sidebar"><button class="brand" data-action="landing">dimora<span>.</span></button><select class="role-picker" aria-label="Cambia profilo">${Object.entries(roles).map(([k,v])=>`<option value="${k}" ${k===state.role?'selected':''}>${v.name}</option>`).join('')}</select>${r.nav.map((p,i)=>`<button class="navitem ${p===state.page?'active':''}" data-action="nav:${p}">${['⌂','▦','▤','◷','€','↗','▥','♧','⚙'][i]} &nbsp; ${p}</button>`).join('')}<div class="sidefoot"><button class="navitem" data-action="tour">▷ Percorso guidato</button><button class="navitem" data-action="reset">↺ Ricomincia demo</button></div></aside><main class="content"><div class="toolbar"><span>${r.label} &nbsp; / &nbsp; ${esc(state.selected)}</span>${state.page==='Documenti'?`<input id="search" aria-label="Cerca documenti" placeholder="Cerca un documento…" value="${esc(state.query)}">`:'<span>Ambiente dimostrativo</span>'}</div>${state.tour?`<div class="guide"><strong>Il tuo percorso · ${state.step+1} di ${r.journey.length}</strong><p>${esc(r.journey[state.step])} · Esplora le azioni di questa schermata, poi prosegui.</p><div class="actions">${button(state.step===r.journey.length-1?'Concludi il percorso ✓':'Prossimo passo →','next',true)}<button class="link" data-action="end-tour">Esplora liberamente</button></div></div>`:''}<div class="pagehead"><div><div class="eyebrow" style="margin-bottom:7px">${home?'Benvenuto nella tua esperienza':esc(state.selected)}</div><h1>${home?(state.role==='home'?'Tutto quello che chiami casa.':state.role==='agency'?'Il valore inizia dall’ordine.':'Ogni edificio ha una storia.'):esc(state.page)}</h1><p>${home?r.benefit:'Una vista semplice. I dettagli quando ti servono.'}</p></div>${['Documenti','La mia casa'].includes(state.page)?button('+ Aggiungi','import'):''}</div>${pageContent()}<div class="source">Simulazione promozionale basata sulla V5 consolidata e sul catalogo Home/Partner. Le funzioni mostrate possono essere concept; non attestano disponibilità commerciale o conformità.</div></main></div>`}
function route(){const h=decodeURIComponent(location.hash.slice(1));if(!h){$('#app').innerHTML=landing();return}let [r,p]=h.split('/');if(!roles[r]){location.hash='';return}state.role=r;state.page=roles[r].nav.includes(p)?p:roles[r].nav[0];render()}function render(){if(!location.hash)$('#app').innerHTML=landing();else $('#app').innerHTML=workspace()}function go(r,p){state.role=r;state.page=p||roles[r].nav[0];state.filter='Tutti';state.query='';let hash=encodeURIComponent(r)+'/'+encodeURIComponent(state.page);if(location.hash.slice(1)===hash)render();else location.hash=hash;window.scrollTo(0,0)}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}function modal(title,body,actions=''){ $('#modal').innerHTML=`<button class="close" data-action="close" aria-label="Chiudi">×</button><div class="eyebrow">Dimora · simulazione</div><h2>${esc(title)}</h2>${body}<div class="actions">${actions||button('Ho capito','close',true)}</div>`;if(!$('#dialog').open)$('#dialog').showModal()}function close(){ $('#dialog').close() }
function importModal(){modal('Un documento. Tutto collegato.',`<p>Prova un esempio già pronto, senza caricare documenti personali.</p><label for="sample">Documento dimostrativo</label><select id="sample"><option>Fattura acquisto demo</option><option>Bolletta luce demo</option><option>Foto libretto demo</option><option>Planimetria demo</option></select><p class="tiny" style="margin-top:18px">La lettura e le proposte sono simulate. Nella V5 la disponibilità dipende dal documento e dal percorso di acquisizione.</p>`,button('Mostra le proposte →','review'))}
function review(){const kind=$('#sample')?.value||'Fattura acquisto demo';state.sample=kind;const bill=kind.includes('Bolletta'),plan=kind.includes('Planimetria'),photo=kind.includes('Foto');modal('Rivedi prima di confermare',`<p>Fonte: ${esc(kind)} · dati fittizi. Puoi correggere ogni proposta.</p><label for="proposal-name">${plan?'Ambiente':photo?'Impianto':'Descrizione'}</label><input id="proposal-name" value="${bill?'Fornitura luce':plan?'Soggiorno':photo?'Caldaia':'Macchina da caffè'}">${!plan&&!photo?'<label for="proposal-cost">Importo (€)</label><input id="proposal-cost" type="number" min="0" step="0.01" value="'+(bill?'86.40':'499')+'">':''}<div class="notice" style="background:#f0f4e9;padding:15px;margin-top:18px;border-radius:8px;font-size:13px">${bill?'Solo spesa: nessun oggetto creato da una bolletta.':plan?'Ambiente proposto: nessuna misura o conformità dedotta.':photo?'Dati tecnici da completare. Nessuna scadenza normativa dedotta.':'Oggetto + spesa + contatto del rivenditore collegati alla stessa fonte. Garanzia non dedotta.'}</div>`,button('Conferma nella demo','confirm-review')+button('Torna al documento','import',true))}
function details(name){modal(name,`<p>${state.role==='home'?'Casa · memoria personale':'Edificio · memoria tecnica'} · esempio dimostrativo</p>${row('Documenti e fonti',name==='Macchina da caffè'?'Fattura acquisto demo':'Manuale e documento tecnico dimostrativi','document:Manuale caldaia','Consulta')}${row('Garanzia','Inserita manualmente o da completare. Nessuna copertura presunta.','warranty','Gestisci')}${row('Attività e storico','Interventi e promemoria collegati','complete','Apri')}${row('Professionista','Tecnico Demo · contatto fittizio','contact','Apri')}`,button('Torna alla vista','close',true))}
function share(gift=false){modal(gift?'Prepara la Home Gift':'Scegli cosa condividere',`<p>Immobile: ${esc(state.selected)}. Solo i contenuti selezionati entreranno nel manifesto dimostrativo.</p><label class="check"><input type="checkbox" id="share1" checked><span>Planimetria della casa<small>Versione 1 · documento della casa</small></span></label><label class="check"><input type="checkbox" id="share2" checked><span>Manuale e scheda impianto<small>Versione 1 · fonte e memoria strutturata</small></span></label><p class="tiny">Esclusi: fatture personali, contatti privati e accesso permanente del partner alla Home.</p><label for="recipient">Email destinatario (fittizia)</label><input id="recipient" type="email" placeholder="persona@example.test"><label class="check"><input id="rights" type="checkbox"><span>Ho esaminato selezione e diritti di condivisione nella demo.</span></label>`,button('Anteprima manifesto',gift?'gift-preview':'share-preview'))}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const [a,...rest]=el.dataset.action.split(':');const v=rest.join(':');switch(a){case'landing':state.tour=false;location.hash='';break;case'scroll':document.getElementById(v)?.scrollIntoView({behavior:'smooth'});break;case'enter':state.tour=false;go(v);break;case'nav':go(state.role,v);break;case'close':close();break;case'demo':go('home','Documenti');importModal();break;case'import':importModal();break;case'review':review();break;case'confirm-review':{let name=$('#proposal-name').value.trim();let cost=$('#proposal-cost')?Number($('#proposal-cost').value):null;if(!name||cost!==null&&(!Number.isFinite(cost)||cost<0)){toast('Controlla descrizione e importo.');break}if(!state.extraDocs.some(d=>d.name===state.sample)){state.extraDocs.push({name:state.sample,type:state.sample.includes('Bolletta')?'Spese':'Casa',source:'Aggiunto nella demo · origine simulata',icon:'▤'});if(cost!==null)state.expenses.push({name,amount:cost});}if(!state.sample.includes('Bolletta')&&!state.sample.includes('Planimetria')&&!state.objects.includes(name))state.objects.push(name);state.reviewed=true;state.changes.push('Acquisto confermato');close();go(state.role,state.role==='home'?'Documenti':'Impianti e memoria');toast('Informazioni confermate nella demo. Nessun dato reale elaborato.');break}case'detail':details(v);break;case'filter':state.filter=v;render();break;case'document':modal(v,`<div style="padding:25px;background:#f6f7f1;border:1px solid #dfe5db;border-radius:8px"><div class="eyebrow">Facsimile · nessun originale personale</div><h3>${esc(v)}</h3><p>Documento illustrativo per ${esc(state.selected)}.</p><hr style="border:0;border-top:1px solid #dfe5db"><p>Fonte: ${v.includes('ascensore')?'Studio Verdi · versione 3':'Archivio personale · versione 1'}<br>Le informazioni rimangono collegate al documento di origine.</p></div>`,button('Chiudi anteprima','close',true));break;case'complete':modal(state.activity,`<p>Attività dimostrativa · Caldaia · 5 novembre 2026</p><label for="nextdate">Prossimo promemoria</label><input id="nextdate" type="date" value="2027-11-05"><label for="tasknote">Nota dell’intervento</label><textarea id="tasknote" placeholder="Aggiungi un dettaglio…"></textarea>`,button('Completa e prepara promemoria','done'));break;case'done':if(!$('#nextdate').value){toast('Scegli la data del prossimo promemoria.');break}state.completed=true;close();render();toast('Attività completata nella demo. Prossimo promemoria: '+$('#nextdate').value);break;case'select':state.selected=v;go(state.role,state.role==='agency'?'Checklist':'Impianti e memoria');break;case'receive':if(!state.changes.includes(v))state.changes.push(v);render();toast('Ricezione simulata: '+v+'. Il documento resta da verificare.');break;case'request':modal('Richiesta pronta da rivedere',`<p>Anteprima per il proprietario di ${esc(state.selected)}:</p><div class="card"><p>Per completare il fascicolo servono APE e libretto impianto. Potrai caricarli dal link dedicato alla raccolta.</p></div><p class="tiny">Link dimostrativo, nessun messaggio inviato.</p>`,button('Segna come predisposta','request-done'));break;case'request-done':close();toast('Richiesta predisposta nella simulazione. Nessun invio.');break;case'dossier':modal('Dossier · '+v,`<p>${esc(state.selected)} · ${v==='Anteprima'?'scheda divulgabile senza documenti riservati':'selezione di documenti con destinatario da autorizzare'}.</p>${row('Scheda immobile','Dati illustrativi · fonte da verificare',null)}${v==='Riservato'?'<label class="check"><input type="checkbox" checked>Planimetria · versione 1</label><label class="check"><input type="checkbox">APE · se ricevuto e autorizzato</label>':''}<p class="tiny">Nessuna attestazione di conformità o apertura di accessi reali.</p>`,button('Prepara pacchetto demo','dossier-done'));break;case'dossier-done':close();toast('Pacchetto dimostrativo preparato con la selezione indicata.');break;case'gift':share(true);break;case'share':share();break;case'gift-preview':case'share-preview':{if(!$('#rights').checked){toast('Esamina e conferma i diritti nella demo.');break}if(!$('#recipient').checkValidity()||!$('#recipient').value){toast('Inserisci un indirizzo email valido di esempio.');break}const chosen=[$('#share1').checked?'Planimetria v1':null,$('#share2').checked?'Manuale e scheda impianto v1':null].filter(Boolean);if(!chosen.length){toast('Seleziona almeno un contenuto.');break}const mail=$('#recipient').value;state.gift=a==='gift-preview'||state.gift;modal('Manifesto dimostrativo pronto',`<p>Destinatario: ${esc(mail)}</p><p>Inclusi: ${chosen.join(' · ')}.</p><p>Esclusi: documenti personali e dati privati. Nessuna email inviata o copia reale trasferita.</p>`,button(a==='gift-preview'?'Esplora la Home del destinatario →':'Chiudi',a==='gift-preview'?'gift-home':'close'));render();break}case'gift-home':close();go('home');toast('Anteprima Home del destinatario con dati fittizi.');break;case'publish':{let items=[];if($('#pub-doc')?.checked)items.push('Rapporto ascensore v3');if($('#pub-update')?.checked)items.push('Aggiornamento manutenzione');if(!items.length){toast('Seleziona almeno un contenuto.');break}modal('Anteprima pubblicazione',`<p>${esc(state.selected)} · Scala A · unità autorizzate</p><p>Contenuti: ${items.join(' · ')}.</p><p class="tiny">La pubblicazione riguarda la memoria comune. Nessuna modifica automatica alla Home privata.</p>`,button('Conferma simulazione','published'));break}case'published':state.published=true;close();render();toast('Pubblicazione simulata. Nessun documento distribuito realmente.');break;case'condo':go('home','Condominio');break;case'notice':modal('Aggiornamento ascensore','<p>Studio Verdi · Scala A · comunicazione dimostrativa.</p><p>L’intervento è programmato. Puoi leggere l’aggiornamento o preparare comunque una segnalazione.</p>',button('Prepara segnalazione','issue')+button('Chiudi','close',true));break;case'issue':modal('Descrivi il problema','<label for="issue">Cosa hai notato?</label><textarea id="issue" placeholder="Es. luce ingresso non funzionante"></textarea><p class="tiny">Il testo rimane nella simulazione.</p>',button('Prepara segnalazione','issue-done'));break;case'issue-done':if(!$('#issue').value.trim()){toast('Descrivi brevemente il problema.');break}close();toast('Segnalazione predisposta nella demo. Nessun messaggio inviato.');break;case'invite':case'ownership':modal(a==='invite'?'Collega il proprietario':'Cambio proprietario','<p>Scala A · Interno 12 · diritti da verificare.</p><label for="invite-email">Email fittizia</label><input type="email" id="invite-email" placeholder="persona@example.test"><label>Data di efficacia</label><input type="date" value="2026-11-01"><p class="tiny">Al cambio vanno riesaminati gli accessi precedenti. La Home privata del vecchio proprietario non viene trasferita.</p>',button('Prepara invito demo','invited'));break;case'invited':if(!$('#invite-email').value||!$('#invite-email').checkValidity()){toast('Inserisci un indirizzo valido di esempio.');break}state.linked=true;close();render();toast('Invito predisposto. Nessun account creato o accesso reale cambiato.');break;case'warranty':modal('La garanzia, quando la conosci','<p>Non viene dedotta dal solo acquisto. Registra ciò che hai verificato sul documento.</p><label>Tipo</label><select><option>Da verificare</option><option>Garanzia commerciale dichiarata</option></select><label>Data fine dichiarata</label><input type="date">',button('Salva nella demo','saved'));break;case'contact':modal('Tecnico Demo','<p>Contatto fittizio collegato alla fonte dell’intervento.</p><p>Nome: Tecnico Demo<br>Email: tecnico@example.test</p><p class="tiny">Nessun contatto viene chiamato o riceve messaggi.</p>');break;case'plan':modal('Home Pro · proposta di esperienza','<p>Proposte dai documenti, assistente e automazioni con quote trasparenti.</p><p>Prezzi e quantità sono da definire. Nessun acquisto è disponibile nella demo.</p><p>La gestione manuale e l’esportazione dei dati restano nella proposta Home Free.</p>');break;case'preferences':modal('Preferenze demo','<label class="check"><input type="checkbox" checked>Promemoria in app</label><label class="check"><input type="checkbox">Riepilogo email</label><label class="check"><input type="checkbox">Notifiche push</label><p class="tiny">Scelte illustrative: nessun canale collegato.</p>',button('Conferma nella demo','saved')+button('Esporta riepilogo demo','export',true));break;case'export':{let b=new Blob([JSON.stringify({avviso:'Solo dati dimostrativi',documenti:docs.concat(state.extraDocs),spese:state.expenses},null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='dimora-riepilogo-demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);break}case'team':modal('Team e permessi','<p>La tua organizzazione · utenti fittizi.</p>'+row('Giulia · Responsabile','Accessi all’organizzazione e pubblicazioni',null)+row('Luca · Collaboratore','Raccolta e revisione, senza pubblicazione',null)+'<p class="tiny">I profili di questa demo sono liberamente esplorabili; i permessi reali non sono implementati.</p>');break;case'integration':modal('Importa dal tuo lavoro quotidiano','<p>Anteprima di import da file esportati compatibili: selezione, corrispondenza dei campi, revisione e conferma.</p><p>Integrazioni CRM e gestionali sono un’evoluzione da validare. Nessun servizio esterno connesso.</p>',button('Simula importazione di esempio','saved'));break;case'branding':modal('Il marchio sul dossier','<label>Nome studio</label><input value="Studio Verdi"><p class="tiny">Anteprima dimostrativa di co-branding.</p>',button('Conferma anteprima','saved'));break;case'resolve':modal('Illuminazione ingresso','<p>Segnalazione fittizia · da valutare con il professionista incaricato.</p><label>Stato</label><select><option>Ricevuta</option><option>Intervento programmato</option><option>Risolta</option></select>',button('Aggiorna nella demo','saved'));break;case'saved':close();toast('Scelta confermata nella simulazione.');break;case'new':modal(v==='activity'?'Una nuova attività':state.role==='agency'?'Un nuovo fascicolo':'Un nuovo edificio',`<label for="newname">${v==='activity'?'Nome attività':'Indirizzo'}</label><input id="newname" placeholder="${v==='activity'?'Controllo filtro':'Via Esempio 10'}">${v==='activity'?'<label>Data</label><input type="date" value="2026-11-10">':''}`,button('Aggiungi nella demo',v==='activity'?'new-task':'new-property'));break;case'new-task':case'new-property':{let n=$('#newname').value.trim();if(!n){toast('Inserisci un nome.');break}if(a==='new-task')state.activity=n;else state.selected=n;close();go(state.role,a==='new-task'?'Attività':state.role==='agency'?'Checklist':'Impianti e memoria');toast('Esempio aggiunto nella demo.');break}case'tour':state.tour=true;state.step=0;go(state.role,roles[state.role].journey[0]);break;case'next':if(state.step<roles[state.role].journey.length-1){state.step++;go(state.role,roles[state.role].journey[state.step]);}else{state.tour=false;render();modal('Hai esplorato il percorso.','<p>Continua liberamente o cambia profilo per scoprire la casa da un’altra prospettiva.</p>')}break;case'end-tour':state.tour=false;render();break;case'reset':modal('Ricominciare la dimostrazione?','<p>Le sole modifiche simulate di questa sessione saranno azzerate.</p>',button('Ricomincia','reset-confirm')+button('Continua a esplorare','close',true));break;case'reset-confirm':close();location.reload();break;}});
document.addEventListener('change',e=>{if(e.target.matches('.role-picker')){state.tour=false;go(e.target.value)}if(e.target.id==='annual'){let v=Number(e.target.value);if(Number.isFinite(v)&&v>=0&&v<=10000000){state.budget=v;$('#chart').innerHTML=chart(v)}else toast('Inserisci un importo tra 0 e 10 milioni.')}});document.addEventListener('input',e=>{if(e.target.id==='search'){state.query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});window.addEventListener('hashchange',route);route();
